ALTER TABLE public.sales_records ADD COLUMN IF NOT EXISTS vouchers_sold numeric NOT NULL DEFAULT 0 CHECK(vouchers_sold>=0), ADD COLUMN IF NOT EXISTS deposits_taken numeric NOT NULL DEFAULT 0 CHECK(deposits_taken>=0), ADD COLUMN IF NOT EXISTS vouchers_used numeric NOT NULL DEFAULT 0 CHECK(vouchers_used>=0), ADD COLUMN IF NOT EXISTS deposits_used numeric NOT NULL DEFAULT 0 CHECK(deposits_used>=0), ADD COLUMN IF NOT EXISTS deferred_feed boolean NOT NULL DEFAULT false;
ALTER TABLE public.finance_deferred_items ADD COLUMN IF NOT EXISTS source_sales_id uuid REFERENCES public.sales_records(id);
CREATE OR REPLACE FUNCTION public.finance_sales_deferred_save(t uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s sales_records;cfg finance_schedule_settings;rid uuid:=gen_random_uuid();aid uuid;cashid uuid;clearing uuid;rev uuid;svc uuid;disc uuid;tip uuid;ls jsonb:='[]';items jsonb:='[]';uses jsonb:='[]';it finance_deferred_items;amt numeric;remain numeric;sold numeric;used numeric;k text;kind text;d date:=(p->>'date')::date;v text:=p->>'venue';did uuid; BEGIN
IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required for deferred sales';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended('schedule:'||t::text,0));PERFORM finance_assert_open(t,d);
IF d>(now() AT TIME ZONE 'Asia/Hong_Kong')::date OR NOT EXISTS(SELECT 1 FROM venues WHERE tenant_id=t AND name=v AND public.user_has_venue(auth.uid(),id)) THEN RAISE EXCEPTION 'Valid trading date and permitted venue required';END IF;
IF EXISTS(SELECT 1 FROM sales_records WHERE tenant_id=t AND date=d::text AND venue=v) OR EXISTS(SELECT 1 FROM journal_entries WHERE tenant_id=t AND source_type='sales_summary' AND source_id=d::text||'__'||v) THEN RAISE EXCEPTION 'Sales already exist; posted sales cannot be changed';END IF;
SELECT * INTO cfg FROM finance_schedule_settings WHERE tenant_id=t;
FOREACH k IN ARRAY ARRAY['vouchersSold','depositsTaken','vouchersUsed','depositsUsed'] LOOP amt:=coalesce((p->>k)::numeric,0);IF amt<0 OR amt<>round(amt,2) THEN RAISE EXCEPTION 'Deferred amounts must be non-negative cents';END IF;IF amt>0 AND (CASE WHEN k LIKE 'vouchers%' THEN coalesce(cfg.voucher_enabled,false) ELSE coalesce(cfg.deposit_enabled,false) END)=false THEN RAISE EXCEPTION 'Deferred type is not enabled';END IF;END LOOP;
sold:=coalesce((p->>'vouchersSold')::numeric,0)+coalesce((p->>'depositsTaken')::numeric,0);used:=coalesce((p->>'vouchersUsed')::numeric,0)+coalesce((p->>'depositsUsed')::numeric,0);
IF sold+used<=0 OR sold>coalesce((p->>'subtotal')::numeric,0) THEN RAISE EXCEPTION 'Deferred sold amounts must be included in printed subtotal';END IF;
SELECT account_id INTO rev FROM account_mapping_rules WHERE tenant_id=t AND rule_type='sales_revenue' AND match_key=v LIMIT 1;
SELECT account_id INTO svc FROM account_mapping_rules WHERE tenant_id=t AND rule_type='service_charge' AND match_key=v LIMIT 1;
SELECT account_id INTO disc FROM account_mapping_rules WHERE tenant_id=t AND rule_type='sales_discount' AND match_key=v LIMIT 1;
SELECT account_id INTO tip FROM account_mapping_rules WHERE tenant_id=t AND rule_type='tips_payable' AND match_key=v LIMIT 1;
SELECT account_id INTO cashid FROM account_mapping_rules WHERE tenant_id=t AND rule_type='cash_on_hand' AND match_key=v LIMIT 1;
SELECT account_id INTO clearing FROM account_mapping_rules WHERE tenant_id=t AND rule_type='payment_settlement_clearing' AND match_key=v LIMIT 1;
SELECT id INTO aid FROM chart_of_accounts WHERE tenant_id=t AND code='2300' AND account_type='liability';IF aid IS NULL OR rev IS NULL THEN RAISE EXCEPTION 'Deferred liability and venue sales accounts required';END IF;
remain:=0;FOREACH k IN ARRAY ARRAY['visa','mastercard','amex','unionPay','jcb','alipay','wechat','payme','cash','deliveroo','foodpanda','keeta'] LOOP amt:=coalesce((p->>k)::numeric,0);IF amt<0 THEN RAISE EXCEPTION 'Payment cannot be negative';END IF;remain:=remain+amt;IF amt>0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',CASE WHEN k='cash' THEN cashid ELSE clearing END,'debit',amt,'credit',0,'venue',v,'memo',k));END IF;END LOOP;
IF abs(remain-coalesce((p->>'totalSales')::numeric,0))>0.005 OR abs(coalesce((p->>'subtotal')::numeric,0)+coalesce((p->>'serviceCharge')::numeric,0)-abs(coalesce((p->>'discount')::numeric,0))-coalesce((p->>'totalSales')::numeric,0))>0.005 THEN RAISE EXCEPTION 'Sales and payments must balance';END IF;
ls:=ls||jsonb_build_array(jsonb_build_object('account_id',rev,'debit',0,'credit',(p->>'subtotal')::numeric-sold+used,'venue',v,'memo','Earned sales'));
IF sold>0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',aid,'debit',0,'credit',sold,'venue',v));END IF;IF used>0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',aid,'debit',used,'credit',0,'venue',v));END IF;
amt:=coalesce((p->>'serviceCharge')::numeric,0);IF amt>0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',svc,'debit',0,'credit',amt,'venue',v));END IF;
amt:=abs(coalesce((p->>'discount')::numeric,0));IF amt>0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',disc,'debit',amt,'credit',0,'venue',v));END IF;
amt:=abs(coalesce((p->>'cardTips')::numeric,0));IF amt>0 THEN RAISE EXCEPTION 'Card tips require the existing receipt review flow; deferred draft not saved';END IF;
INSERT INTO sales_records(id,tenant_id,date,day,venue,report_number,orders,guests,subtotal,service_charge,discount,total_sales,visa,mastercard,amex,union_pay,jcb,alipay,wechat,payme,cash,deliveroo,foodpanda,keeta,card_tips,receipt_file_url,receipt_file_name,vouchers_sold,deposits_taken,vouchers_used,deposits_used,deferred_feed,service_period_id) VALUES(rid,t,d::text,to_char(d,'Dy'),v,coalesce(p->>'reportNumber',''),coalesce((p->>'orders')::int,0),coalesce((p->>'guests')::int,0),(p->>'subtotal')::numeric,coalesce((p->>'serviceCharge')::numeric,0),-abs(coalesce((p->>'discount')::numeric,0)),(p->>'totalSales')::numeric,coalesce((p->>'visa')::numeric,0),coalesce((p->>'mastercard')::numeric,0),coalesce((p->>'amex')::numeric,0),coalesce((p->>'unionPay')::numeric,0),coalesce((p->>'jcb')::numeric,0),coalesce((p->>'alipay')::numeric,0),coalesce((p->>'wechat')::numeric,0),coalesce((p->>'payme')::numeric,0),coalesce((p->>'cash')::numeric,0),coalesce((p->>'deliveroo')::numeric,0),coalesce((p->>'foodpanda')::numeric,0),coalesce((p->>'keeta')::numeric,0),0,p->>'receiptFileUrl',p->>'receiptFileName',coalesce((p->>'vouchersSold')::numeric,0),coalesce((p->>'depositsTaken')::numeric,0),coalesce((p->>'vouchersUsed')::numeric,0),coalesce((p->>'depositsUsed')::numeric,0),true,nullif(p->>'servicePeriodId','')::uuid);
FOREACH kind IN ARRAY ARRAY['voucher','deposit'] LOOP
amt:=CASE WHEN kind='voucher' THEN coalesce((p->>'vouchersSold')::numeric,0) ELSE coalesce((p->>'depositsTaken')::numeric,0) END;
IF amt>0 THEN INSERT INTO finance_deferred_items(tenant_id,kind,reference,venue,issued_date,amount,expires_on,source_sales_id) VALUES(t,kind,'Sales '||rid::text||' '||kind,v,d,amt,CASE WHEN kind='voucher' THEN (d+make_interval(months=>cfg.voucher_expiry_months))::date ELSE NULL END,rid) RETURNING * INTO it;items:=items||jsonb_build_array(it.id);END IF;
remain:=CASE WHEN kind='voucher' THEN coalesce((p->>'vouchersUsed')::numeric,0) ELSE coalesce((p->>'depositsUsed')::numeric,0) END;
FOR it IN SELECT * FROM finance_deferred_items WHERE tenant_id=t AND status='active' AND finance_deferred_items.kind=kind AND venue=v AND issued_date<=d AND amount>used_amount ORDER BY issued_date,id FOR UPDATE LOOP EXIT WHEN remain<=0;amt:=least(remain,it.amount-it.used_amount);uses:=uses||jsonb_build_array(jsonb_build_object('id',it.id,'amount',amt,'expected_used',it.used_amount));remain:=remain-amt;END LOOP;
IF remain>0 THEN RAISE EXCEPTION 'Not enough active deferred balance; choose the original voucher/deposit first';END IF;END LOOP;
did:=finance_schedule_enqueue(t,d,'sales_deferred','Sales · '||v||' · deferred revenue','Confirmed report amounts; FIFO use within venue and type','sales-deferred:'||rid,ls,jsonb_build_object('sales_id',rid,'sales_fingerprint',md5(to_jsonb((SELECT x FROM sales_records x WHERE id=rid))::text),'sold_items',items,'uses',uses),p->>'receiptFileUrl');RETURN rid;END $$;
REVOKE ALL ON FUNCTION public.finance_sales_deferred_save(uuid,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_sales_deferred_save(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.finance_deferred_sales_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (OLD.deferred_feed OR NEW.vouchers_sold IS DISTINCT FROM OLD.vouchers_sold OR NEW.deposits_taken IS DISTINCT FROM OLD.deposits_taken OR NEW.vouchers_used IS DISTINCT FROM OLD.vouchers_used OR NEW.deposits_used IS DISTINCT FROM OLD.deposits_used) THEN IF (to_jsonb(NEW)-'receipt_file_url'-'receipt_file_name'-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'receipt_file_url'-'receipt_file_name'-'updated_at') THEN RAISE EXCEPTION 'Deferred sales are immutable; use a correction draft';END IF;END IF;IF TG_OP='INSERT' AND NOT NEW.deferred_feed AND NEW.vouchers_sold+NEW.deposits_taken+NEW.vouchers_used+NEW.deposits_used>0 THEN RAISE EXCEPTION 'Use confirmed deferred sales draft flow';END IF;RETURN NEW;END $$;
CREATE TRIGGER deferred_sales_guard BEFORE INSERT OR UPDATE ON public.sales_records FOR EACH ROW EXECUTE FUNCTION public.finance_deferred_sales_guard();
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public._rebuild_journal_from_operations_impl(uuid,uuid,text)'::regprocedure) INTO def;IF position('WHERE s.tenant_id = p_tenant_id' IN def)=0 THEN RAISE EXCEPTION 'Sales source guard unavailable';END IF;def:=replace(def,'WHERE s.tenant_id = p_tenant_id','WHERE NOT s.deferred_feed AND s.tenant_id = p_tenant_id');EXECUTE def;
SELECT pg_get_functiondef('public.finance_schedule_approve(uuid,uuid,date)'::regprocedure) INTO def;
def:=replace(def,'PERFORM finance_assert_open(t,q.entry_date);','PERFORM finance_assert_open(t,q.entry_date); IF q.kind=''sales_deferred'' THEN IF md5(to_jsonb((SELECT x FROM sales_records x WHERE tenant_id=t AND id=(q.source_data->>''sales_id'')::uuid))::text) IS DISTINCT FROM q.source_data->>''sales_fingerprint'' THEN RAISE EXCEPTION ''Sales source changed'';END IF;FOR l IN SELECT * FROM jsonb_array_elements(q.source_data->''uses'') LOOP SELECT * INTO i FROM finance_deferred_items WHERE tenant_id=t AND id=(l->>''id'')::uuid FOR UPDATE;IF i.status<>''active'' OR i.used_amount IS DISTINCT FROM (l->>''expected_used'')::numeric OR i.amount-i.used_amount<(l->>''amount'')::numeric THEN RAISE EXCEPTION ''Deferred balance changed'';END IF;END LOOP;END IF;');
def:=replace(def,'RETURN j;','IF q.kind=''sales_deferred'' THEN UPDATE finance_deferred_items SET status=''active'' WHERE tenant_id=t AND id IN(SELECT value::text::uuid FROM jsonb_array_elements_text(q.source_data->''sold_items''));FOR l IN SELECT * FROM jsonb_array_elements(q.source_data->''uses'') LOOP UPDATE finance_deferred_items SET used_amount=used_amount+(l->>''amount'')::numeric,status=CASE WHEN used_amount+(l->>''amount'')::numeric=amount THEN ''closed'' ELSE ''active'' END WHERE tenant_id=t AND id=(l->>''id'')::uuid;END LOOP;END IF;RETURN j;');IF def NOT LIKE '%Sales source changed%' THEN RAISE EXCEPTION 'Approval integration unavailable';END IF;EXECUTE def;END $$;